def choose_move(observation):
    x, y = observation.get("self_position", (0, 0))
    bw, bh = observation.get("grid_width", 0), observation.get("grid_height", 0)
    resources = observation.get("resources", [])
    obstacles = observation.get("obstacles", [])
    opp = observation.get("opponent_position", (0, 0))
    max_dx = [1, 0, -1, 0, 1]
    max_dy = [0, 1, 0, -1, 0]

    def in_bounds(nx, ny):
        if bw and bh:
            return 0 <= nx < bw and 0 <= ny < bh
        return True

    def dist(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])

    # If resource nearby, move toward it
    best_r = None
    best_d = 999
    for r in resources or []:
        rx = r.get("x", None)
        ry = r.get("y", None)
        if rx is None or ry is None:
            continue
        d = dist((x, y), (rx, ry))
        if d < best_d:
            best_d = d
            best_r = (rx, ry)

    if best_r is not None and best_d > 0:
        rx, ry = best_r
        if rx > x and in_bounds(x+1, y):
            return [1, 0]
        if rx < x and in_bounds(x-1, y):
            return [-1, 0]
        if ry > y and in_bounds(x, y+1):
            return [0, 1]
        if ry < y and in_bounds(x, y-1):
            return [0, -1]

    # Flee from opponent if close
    ox, oy = opp
    if dist((x, y), (ox, oy)) <= 2:
        if ox > x and in_bounds(x-1, y):
            return [-1, 0]
        if ox < x and in_bounds(x+1, y):
            return [1, 0]
        if oy > y and in_bounds(x, y-1):
            return [0, -1]
        if oy < y and in_bounds(x, y+1):
            return [0, 1]

    # Otherwise try to move toward center or simple patrol
    cx = bw // 2 if bw else x
    cy = bh // 2 if bh else y
    if cx > x and in_bounds(x+1, y):
        return [1, 0]
    if cx < x and in_bounds(x-1, y):
        return [-1, 0]
    if cy > y and in_bounds(x, y+1):
        return [0, 1]
    if cy < y and in_bounds(x, y-1):
        return [0, -1]

    # Fallback: stay
    return [0, 0]
